using DigitalPaymentSystem_ILTC.Helpers;
using DigitalPaymentSystem_ILTC.Models;
using Microsoft.VisualBasic;
using StackExchange.Redis;

namespace DigitalPaymentSystem_ILTC.Constants
{
    public class DatabaseConfig
    {
        // Get Database Connection
        public readonly static string DB_CONN = AppConfiguration.Configuration.GetConnectionString("ILGHIConnectionString");

        // Get Schema Name
        public readonly static string DB_SCHEMA = AppConfiguration.Configuration.GetConnectionString("DBSchemaName");


        // ------------------ Tables ------------------
        // Hash Table - Key Value Master
        public readonly static string TABLE_TBL_DPS_KEY_VALUE_MST = DB_SCHEMA + "TBL_DPS_KEY_VALUE_MST";
        public readonly static string TABLE_TBL_DPS_DB_QUERIES_KEY_VALUE_MST = DB_SCHEMA + "TBL_DPS_DB_QUERIES_KEY_VALUE_MST";

        // Cloud Watch Logs
        public readonly static string TABLE_TBL_DPS_CLOUD_WATCH_LOGS = DB_SCHEMA + "TBL_DPS_CLOUD_WATCH_LOGS";

        // APIAuthenticationAttribute
        public readonly static string TABLE_TBL_DPS_APPLICATION_MST = DB_SCHEMA + "TBL_DPS_APPLICATION_MST";

        // Template Table
        public readonly static string TABLE_TBL_DPS_TEMPLATE_MST = DB_SCHEMA + "TBL_DPS_TEMPLATE_MST";

        // Transaction Entry Table
        public readonly static string TABLE_TBL_DPS_TRANSACTION_DETAILS = DB_SCHEMA + "TBL_DPS_TRANSACTION_DETAILS";

        // Order Details Table
        public readonly static string TABLE_TBL_DPS_ORDER_DETAILS = DB_SCHEMA + "TBL_DPS_ORDER_DETAILS";

        // Payment Details Table
        public readonly static string TABLE_TBL_DPS_PAYMENT_DETAILS = DB_SCHEMA + "TBL_DPS_PAYMENT_DETAILS";

        // API Call Logs Table
        public readonly static string TABLE_TBL_DPS_INTEGRATION_API_LOGS = DB_SCHEMA + "TBL_DPS_INTEGRATION_API_LOGS";

        // BreakIn Details Table
        public readonly static string TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS = DB_SCHEMA + "TBL_DPS_NYSA_BREAKIN_DETAILS";
        public readonly static string TABLE_TBL_DPS_NYSA_BREAKIN_PI_SUBLOCATION_MST = DB_SCHEMA + "TBL_DPS_NYSA_BREAKIN_PI_SUBLOCATION_MST";

        // Refund Details Table
        public readonly static string TABLE_TBL_DPS_REFUND_DETAILS = DB_SCHEMA + "TBL_DPS_REFUND_DETAILS";
        public readonly static string TABLE_TBL_DPS_REFUND_MAPPING_DETAILS = DB_SCHEMA + "TBL_DPS_REFUND_MAPPING_DETAILS";

        // Penny Drop Details Table
        public readonly static string TABLE_TBL_DPS_PENNY_DROP_DETAILS = DB_SCHEMA + "TBL_DPS_PENNY_DROP_DETAILS";

        // Dashboard Email Login Table
        public readonly static string TABLE_TBL_DPS_DASHBOARD_EMAIL_LOGIN_MST = DB_SCHEMA + "TBL_DPS_DASHBOARD_EMAIL_LOGIN_MST";

        // Products Master Table for Callback reqd
        public readonly static string TABLE_TBL_DPS_PRODUCT_MST = DB_SCHEMA + "TBL_DPS_PRODUCT_MST";

        // AuthToken Data Table
        public readonly static string TABLE_TBL_DPS_AUTHTOKEN_DETAILS = DB_SCHEMA + "TBL_DPS_AUTHTOKEN_DETAILS";

        // Gateway Customer Details Table
        public readonly static string TABLE_TBL_DPS_GATEWAY_CUSTOMER_DETAILS = DB_SCHEMA + "TBL_DPS_GATEWAY_CUSTOMER_DETAILS";


        // ------------------ Views ------------------
        // STP Retry Resync Cases View
        public readonly static string VIEW_VW_DPS_STP_RETRY_RESYNC_CASES = DB_SCHEMA + "VW_DPS_STP_RETRY_RESYNC_CASES";

        // NSTP Retry Resync Cases View
        public readonly static string VIEW_VW_DPS_NSTP_RETRY_RESYNC_CASES = DB_SCHEMA + "VW_DPS_NSTP_RETRY_RESYNC_CASES";

        // Refund Cases View
        public readonly static string VIEW_VW_DPS_REFUND_CASES = DB_SCHEMA + "VW_DPS_REFUND_CASES";

        // Dashboard Transaction Summary View
        public readonly static string VIEW_VW_DPS_DASHBOARD_TRANSACTION_SUMMARY = DB_SCHEMA + "VW_DPS_DASHBOARD_TRANSACTION_SUMMARY";

        // Dashboard Event Logs Table
        public readonly static string TABLE_TBL_DPS_DASHBOARD_EVENT_LOGS = DB_SCHEMA + "TBL_DPS_DASHBOARD_EVENT_LOGS";

        // Active Payment Gateway Table
        public readonly static string TABLE_TBL_DPS_PAYMENT_GATEWAY_MST = DB_SCHEMA + "TBL_DPS_PAYMENT_GATEWAY_MST";

        // EMI Recurring Details Table
        public readonly static string TABLE_TBL_DPS_EMI_RECURRING_DETAILS = DB_SCHEMA + "TBL_DPS_EMI_RECURRING_DETAILS";

        // ------------------ DB Hash Table Mappings ------------------
        // Insert Cloud Watch Creation Logs in DB
        // 1
        public static string INSERT_CLOUD_WATCH_LOGS => DataLoader.DBQueriesKeyValueStore["INSERT_CLOUD_WATCH_LOGS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_CLOUD_WATCH_LOGS + " (SERVER_IP, ERROR_TEXT) VALUES(@SERVER_IP, @ERROR_TEXT)";

        // Create Token check if Credentials are valid
        // 2
        public static string IS_VALID_AUTH => DataLoader.DBQueriesKeyValueStore["IS_VALID_AUTH"]?.ToString() ?? "SELECT COUNT(1) FROM " + TABLE_TBL_DPS_APPLICATION_MST + " WHERE APPLICATION_NAME = @USERNAME AND APPLICATION_ID = @PASSWORD;";

        // Get Next Transaction ID from Sequence
        // 3
        public static string GET_TRANSACTION_ID_SEQ => DataLoader.DBQueriesKeyValueStore["GET_TRANSACTION_ID_SEQ"]?.ToString() ?? "SELECT NEXTVAL('" + DB_SCHEMA + "TRANSACTION_ID_SEQ')";

        // Check if Template ID is valid for given Product and Application Name
        // 4
        public static string CHECK_VALID_TEMPLATE => DataLoader.DBQueriesKeyValueStore["CHECK_VALID_TEMPLATE"]?.ToString() ?? "SELECT IS_ACTIVE FROM " + TABLE_TBL_DPS_TEMPLATE_MST + " WHERE TEMPLATE_ID = @TEMPLATE_ID AND PRODUCT = @PRODUCT AND APPLICATION_NAME = @APPLICATION_NAME;";

        // Insert Transaction Details received from Channel Application in Transaction Table
        // 5
        public static string INSERT_TRANSACTION_DETAILS => DataLoader.DBQueriesKeyValueStore["INSERT_TRANSACTION_DETAILS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_TRANSACTION_DETAILS + "(TRANSACTION_ID, APPLICATION_NAME, TRACE_ID, TOTAL_AMOUNT, PROPOSAL_NUMBER, PROPOSAL_AMOUNT, PROPOSAL_STATUS, PROPOSAL_START_DATE, DEAL_ID, CUSTOMER_ID, INTERMEDIARY_CODE, NAME, EMAIL, MOBILE_NUMBER, PRODUCT, JOURNEY_TYPE, CORE, TEMPLATE_ID, PAYER_TYPE, SEND_PAYMENT_LINK, USER_ID, IS_NSTP_FLOW, BUSINESS_VERTICAL, SUB_VERTICAL, MARKETING_OFFICER, PROPOSER_CODE, IS_MOBILE_USER, CHANNEL_APPLICATION_DETAILS, JUSPAY_UDF1, JUSPAY_UDF2, JUSPAY_UDF3, JUSPAY_UDF4, JUSPAY_UDF5, JUSPAY_UDF6, JUSPAY_UDF7, JUSPAY_UDF8, JUSPAY_UDF9, JUSPAY_UDF10, RM_TEXT, PG_NAME) VALUES(@TRANSACTION_ID, @APPLICATION_NAME, @TRACE_ID, @TOTAL_AMOUNT, @PROPOSAL_NUMBER, @PROPOSAL_AMOUNT, @PROPOSAL_STATUS, @PROPOSAL_START_DATE, @DEAL_ID, @CUSTOMER_ID, @INTERMEDIARY_CODE, @NAME, @EMAIL, @MOBILE_NUMBER, @PRODUCT, @JOURNEY_TYPE, @CORE, @TEMPLATE_ID, @PAYER_TYPE, @SEND_PAYMENT_LINK, @USER_ID, @IS_NSTP_FLOW, @BUSINESS_VERTICAL, @SUB_VERTICAL, @MARKETING_OFFICER, @PROPOSER_CODE, @IS_MOBILE_USER, @CHANNEL_APPLICATION_DETAILS, @JUSPAY_UDF1, @JUSPAY_UDF2, @JUSPAY_UDF3, @JUSPAY_UDF4, @JUSPAY_UDF5, @JUSPAY_UDF6, @JUSPAY_UDF7, @JUSPAY_UDF8, @JUSPAY_UDF9, @JUSPAY_UDF10, @RM_TEXT, @PG_NAME);";

        // Update Payment Link for Transaction ID in Transaction Table
        // 6
        public static string UPDATE_PAYMENT_LINK => DataLoader.DBQueriesKeyValueStore["UPDATE_PAYMENT_LINK"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " SET PAYMENT_URL = @PAYMENT_URL, MODIFIED_ON = CURRENT_TIMESTAMP WHERE TRANSACTION_ID = @TRANSACTION_ID;";

        // Log Integration API Calls
        // 7
        public static string LOG_INTEGRATION_API => DataLoader.DBQueriesKeyValueStore["LOG_INTEGRATION_API"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_INTEGRATION_API_LOGS + "(TRACE_ID, REQUEST, RESPONSE, API_URL, MODULE, PROPOSAL_NUMBER, STATUS_CODE, FLOW_TYPE, RESPONSE_TIME) VALUES (@TRACE_ID, @REQUEST, @RESPONSE, @API_URL, @MODULE, @PROPOSAL_NUMBER, @STATUS_CODE, @FLOW_TYPE, @RESPONSE_TIME);";

        // Fetch transaction details by Transaction ID and Trace ID
        // 8
        public static string GET_TRANSACTION_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_TRANSACTION_DETAILS"]?.ToString() ?? "SELECT T.*, PD.IS_BREAKIN_REQ, PD.DPS_ORDER_ID, PD.CREATED_ON AS PAYMENT_CREATED_ON FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T LEFT JOIN " + TABLE_TBL_DPS_PAYMENT_DETAILS + " PD ON (T.JOURNEY_TYPE <> 'ADVANCE' AND T.TRANSACTION_ID = PD.TRANSACTION_ID AND T.PROPOSAL_NUMBER = PD.PROPOSAL_NUMBER) OR (T.JOURNEY_TYPE = 'ADVANCE' AND T.TRANSACTION_ID = PD.TRANSACTION_ID) WHERE T.TRANSACTION_ID = @TRANSACTION_ID AND T.TRACE_ID = @TRACE_ID;";

        // Fetch template details by Template ID
        // 9
        public static string GET_TEMPLATE_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_TEMPLATE_DETAILS"]?.ToString() ?? "SELECT * FROM " + TABLE_TBL_DPS_TEMPLATE_MST + " WHERE TEMPLATE_ID = @TEMPLATE_ID;";

        // Fetch return loader url by Template ID to redirect from Juspay to our page
        // 10
        public static string GET_TEMPLATE_LOADER_RETURN_URL => DataLoader.DBQueriesKeyValueStore["GET_TEMPLATE_LOADER_RETURN_URL"]?.ToString() ?? "SELECT RETURN_LOADER_URL FROM " + TABLE_TBL_DPS_TEMPLATE_MST + " WHERE TEMPLATE_ID = @TEMPLATE_ID  LIMIT 1;";

        // Fetch Juspay Merchant ID from Application Master Table
        // 11
        public static string GET_JUSPAY_MERCHANT_ID => DataLoader.DBQueriesKeyValueStore["GET_JUSPAY_MERCHANT_ID"]?.ToString() ?? "SELECT JUSPAY_MID FROM " + TABLE_TBL_DPS_APPLICATION_MST + " WHERE APPLICATION_NAME = @APPLICATION_NAME LIMIT 1;";

        // Insert Order Details
        // 12
        public static string INSERT_ORDER_DETAILS => DataLoader.DBQueriesKeyValueStore["INSERT_ORDER_DETAILS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_ORDER_DETAILS + " (TRANSACTION_ID, TRACE_ID, AMOUNT, ORDER_ID, PAYMENT_MODE, DPS_ORDER_ID, GATEWAY_CUSTOMER_ID) " + "VALUES(@TRANSACTION_ID, @TRACE_ID, @AMOUNT, @ORDER_ID, @PAYMENT_MODE, @DPS_ORDER_ID, @GATEWAY_CUSTOMER_ID);";

        // Insert Payment Details received from Webhook
        // 13
        public static string INSERT_PAYMENT_DETAILS => DataLoader.DBQueriesKeyValueStore["INSERT_PAYMENT_DETAILS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_PAYMENT_DETAILS + " (PROPOSAL_NUMBER, TRACE_ID, TRANSACTION_ID, AMOUNT, ORDER_ID, AUTH_CODE, PAYMENT_MODE, DPS_ORDER_ID, ORDER_STATUS, MANDATE_ID, PROPOSAL_AMOUNT, PROPOSAL_TYPE, CORE) VALUES(@PROPOSAL_NUMBER, @TRACE_ID, @TRANSACTION_ID, @AMOUNT, @ORDER_ID, @AUTH_CODE, @PAYMENT_MODE, @DPS_ORDER_ID, @ORDER_STATUS, @MANDATE_ID, @PROPOSAL_AMOUNT, @PROPOSAL_TYPE, @CORE);";

        // Get Payment Details for making request body for Payment Entry and Tagging
        // 14
        public static string GET_PAYMENT_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_PAYMENT_DETAILS"]?.ToString() ?? "SELECT T.PROPOSAL_NUMBER, T.PROPOSAL_STATUS, T.CORE, T.TRACE_ID, T.TRANSACTION_ID, T.TOTAL_AMOUNT, T.CREATED_ON, T.PAYER_TYPE, T.DEAL_ID, T.INTERMEDIARY_CODE, T.CUSTOMER_ID, T.JOURNEY_TYPE, A.PF_MID, A.ARTEMIS_MID, A.REVERSE_SYNC_URL, O.PAYMENT_MODE, T.PRODUCT, T.APPLICATION_NAME, T.IS_NSTP_FLOW, T.BUSINESS_VERTICAL, T.SUB_VERTICAL, T.MARKETING_OFFICER, T.PROPOSER_CODE, T.CHANNEL_APPLICATION_DETAILS, T.INSTALLMENT_NUMBER, T.INSTALLMENT_AMOUNT, O.GATEWAY_CUSTOMER_ID, T.PROPOSAL_AMOUNT, T.PROPOSAL_TYPE, T.CORE, T.PROPOSAL_ID, T.IS_ILEMI_PROPOSAL_MOD_REQD FROM " + TABLE_TBL_DPS_ORDER_DETAILS + " O INNER JOIN " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T ON O.TRANSACTION_ID = T.TRANSACTION_ID INNER JOIN " + TABLE_TBL_DPS_APPLICATION_MST + " A ON A.APPLICATION_NAME = T.APPLICATION_NAME WHERE O.ORDER_ID = @ORDER_ID;";

        // Update Core Policy Number in Payment Details Table
        // 15
        public static string UPDATE_CORE_POLICY_NUMBER => DataLoader.DBQueriesKeyValueStore["UPDATE_CORE_POLICY_NUMBER"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_PAYMENT_DETAILS + " SET POLICY_NUMBER = @POLICY_NUMBER, MODIFIED_ON = CURRENT_TIMESTAMP WHERE PROPOSAL_NUMBER = @PROPOSAL_NUMBER;";

        // Fetch Proposal Details from Payment Details Table by Proposal Number for Refund Processing
        // 16
        public static string FETCH_REFUND_DETAILS => DataLoader.DBQueriesKeyValueStore["FETCH_REFUND_DETAILS"]?.ToString() ?? "SELECT P.TRACE_ID, T.CORE, P.DPS_ORDER_ID, T.CHANNEL_APPLICATION_DETAILS, P.AUTH_CODE, P.PAYMENT_ID, T.PROPOSAL_AMOUNT, T.PRODUCT, T.APPLICATION_NAME, T.PROPOSAL_START_DATE, T.PAYER_TYPE, T.CUSTOMER_ID, R.PROPOSAL_NUMBER AS REFUND_PROPOSAL_NUMBER, R.VOUCHER_NUMBER, R.REFUND_STATUS, P.POLICY_NUMBER, R.REFUND_ID FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T INNER JOIN " + TABLE_TBL_DPS_PAYMENT_DETAILS + " P ON T.PROPOSAL_NUMBER = P.PROPOSAL_NUMBER AND T.TRANSACTION_ID = P.TRANSACTION_ID LEFT JOIN " + TABLE_TBL_DPS_REFUND_DETAILS + " R ON P.PROPOSAL_NUMBER = R.PROPOSAL_NUMBER AND P.TRANSACTION_ID = R.TRANSACTION_ID WHERE P.PROPOSAL_NUMBER = @PROPOSAL_NUMBER AND P.TRANSACTION_ID = @TRANSACTION_ID AND P.AUTH_CODE = @AUTH_CODE;";

        // Update resync status in Payment Details Table
        // 17
        public static string UPDATE_RESYNC_STATUS => DataLoader.DBQueriesKeyValueStore["UPDATE_RESYNC_STATUS"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_PAYMENT_DETAILS + " SET RESYNC_STATUS = 'Y', MODIFIED_ON = CURRENT_TIMESTAMP WHERE PROPOSAL_NUMBER = @PROPOSAL_NUMBER;";

        // Get Product from Proposal Number
        // 18
        public static string GET_PRODUCT_FROM_PROPOSALNO => DataLoader.DBQueriesKeyValueStore["GET_PRODUCT_FROM_PROPOSALNO"]?.ToString() ?? "SELECT PRODUCT FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " WHERE PROPOSAL_NUMBER = @PROPOSAL_NUMBER;";

        // Insert BreakIn Details
        // 19
        public static string INSERT_BREAKIN_DETAILS => DataLoader.DBQueriesKeyValueStore["INSERT_BREAKIN_DETAILS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " (TRACE_ID, TRANSACTION_ID, PROPOSAL_NUMBER, INSPECTION_TYPE, BREAKIN_ADDRESS, BREAKIN_PINCODE, BREAKIN_CITY, BREAKIN_STATE) VALUES(@TRACE_ID, @TRANSACTION_ID, @PROPOSAL_NUMBER, @INSPECTION_TYPE, @BREAKIN_ADDRESS, @BREAKIN_PINCODE, @BREAKIN_CITY, @BREAKIN_STATE);";

        // Update BreakIn Details
        // 20
        public static string UPDATE_BREAKIN_DETAILS => DataLoader.DBQueriesKeyValueStore["UPDATE_BREAKIN_DETAILS"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " SET BREAKIN_ID = @BREAKIN_ID, STATUS = @STATUS, REMARK = @REMARK, MODIFIED_ON = CURRENT_TIMESTAMP, VRN = @VRN WHERE PROPOSAL_NUMBER = @PROPOSAL_NUMBER;";

        // Update BreakIn Status
        // 21
        public static string UPDATE_BREAKIN_STATUS => DataLoader.DBQueriesKeyValueStore["UPDATE_BREAKIN_STATUS"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " SET STATUS = @STATUS, REMARK = @REMARKS, INSPECTION_DATE = @INSPECTION_DATE, MODIFIED_ON = NOW() WHERE BREAKIN_ID = @BREAKINID";

        // Get BreakIn Clear Inspection Details
        // 22
        public static string GET_BREAKIN_CLEAR_INSPECTION_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_BREAKIN_CLEAR_INSPECTION_DETAILS"]?.ToString() ?? "SELECT T.PROPOSAL_NUMBER, T.PROPOSAL_START_DATE, T.DEAL_ID, T.TRACE_ID FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T INNER JOIN " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " B ON T.PROPOSAL_NUMBER = B.PROPOSAL_NUMBER AND T.TRANSACTION_ID = B.TRANSACTION_ID WHERE B.BREAKIN_ID = @BREAKIN_ID;";

        // Get Transaction Details by BreakIn ID
        // 23
        public static string GET_TRANSACTION_DETAILS_BY_BREAKIN_ID => DataLoader.DBQueriesKeyValueStore["GET_TRANSACTION_DETAILS_BY_BREAKIN_ID"]?.ToString() ?? "SELECT TD.TRANSACTION_ID, TD.TRACE_ID, TD.CREATED_ON, TD.CORE, TD.TOTAL_AMOUNT, TD.PAYER_TYPE, AM.PF_MID, AM.ARTEMIS_MID, AM.REVERSE_SYNC_URL, PD.AUTH_CODE, PD.PAYMENT_ID, PD.NO_OF_ATTEMPTS, PD.PROPOSAL_NUMBER, TD.PROPOSAL_STATUS, PD.POLICY_NUMBER, TD.DEAL_ID, TD.CUSTOMER_ID, TD.INTERMEDIARY_CODE, TD.CHANNEL_APPLICATION_DETAILS FROM " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " BD INNER JOIN " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " TD ON BD.PROPOSAL_NUMBER = TD.PROPOSAL_NUMBER AND BD.TRANSACTION_ID = TD.TRANSACTION_ID INNER JOIN " + TABLE_TBL_DPS_PAYMENT_DETAILS + " PD ON TD.PROPOSAL_NUMBER = PD.PROPOSAL_NUMBER AND TD.TRANSACTION_ID = PD.TRANSACTION_ID INNER JOIN " + TABLE_TBL_DPS_APPLICATION_MST + " AM ON TD.APPLICATION_NAME = AM.APPLICATION_NAME WHERE BD.BREAKIN_ID = @BREAKINID;";

        // Get BreakIn Details by ID
        // 24
        public static string GET_BREAKIN_DETAILS_BY_ID => DataLoader.DBQueriesKeyValueStore["GET_BREAKIN_DETAILS_BY_ID"]?.ToString() ?? "SELECT TRACE_ID, VRN FROM " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " WHERE BREAKIN_ID = @BREAKIN_ID;";

        // Fetch order status, proposal status, trace id, transaction id, application name by proposal number from transactions table and payments table
        // 25
        public static string GET_ORDER_AND_PROPOSAL_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_ORDER_AND_PROPOSAL_DETAILS"]?.ToString() ?? "SELECT T.PROPOSAL_STATUS, T.PROPOSAL_NUMBER, T.APPLICATION_NAME, T.TEMPLATE_ID, T.PRODUCT, T.CORE, T.DEAL_ID, T.INTERMEDIARY_CODE, O.DPS_ORDER_ID, T.JOURNEY_TYPE, T.PG_NAME, T.PRE_PAYMENT_RETURN_URL FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T INNER JOIN " + TABLE_TBL_DPS_ORDER_DETAILS + " O ON T.TRANSACTION_ID = O.TRANSACTION_ID WHERE T.TRANSACTION_ID = @TRANSACTION_ID AND DPS_ORDER_ID = @DPS_ORDER_ID;";

        // Get Next IAS ID from Sequence
        // 26
        public static string GET_IAS_ID_SEQ => DataLoader.DBQueriesKeyValueStore["GET_IAS_ID_SEQ"]?.ToString() ?? "SELECT NEXTVAL('" + DB_SCHEMA + "IAS_ID_SEQ')";

        // Update IAS ID for Proposal Number in Transaction Table
        // 27
        public static string UPDATE_IAS_ID => DataLoader.DBQueriesKeyValueStore["UPDATE_IAS_ID"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " SET IAS_ID = @IAS_ID, MODIFIED_ON = CURRENT_TIMESTAMP WHERE PROPOSAL_NUMBER = @PROPOSAL_NUMBER;";

        // Fetch return status url by Template ID to redirect from our loader page to our success/breakin/failed page
        // 28
        public static string GET_TEMPLATE_RETURN_STATUS_URL => DataLoader.DBQueriesKeyValueStore["GET_TEMPLATE_RETURN_STATUS_URL"]?.ToString() ?? "SELECT RETURN_STATUS_URL FROM " + TABLE_TBL_DPS_TEMPLATE_MST + " WHERE TEMPLATE_ID = @TEMPLATE_ID;";

        // Fetch Proposal Number and Policy Number from Transaction ID from Payment Table
        // 29
        public static string GET_POLICYDETAILS_BY_TRANSACTIONID => DataLoader.DBQueriesKeyValueStore["GET_POLICYDETAILS_BY_TRANSACTIONID"]?.ToString() ?? "SELECT P.PROPOSAL_NUMBER, P.POLICY_NUMBER, P.IS_BREAKIN_REQ, T.JOURNEY_TYPE, B.BREAKIN_ID, B.INSPECTION_TYPE, T.PROPOSAL_START_DATE, T.PROPOSAL_END_DATE, T.PROPOSAL_AMOUNT, T.PED, T.SUM_INSURED, T.IS_SENIORCITIZEN, T.PROPOSAL_TYPE FROM " + TABLE_TBL_DPS_PAYMENT_DETAILS + " P JOIN " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T ON T.PROPOSAL_NUMBER = P.PROPOSAL_NUMBER AND T.TRANSACTION_ID = P.TRANSACTION_ID LEFT JOIN " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " B ON P.PROPOSAL_NUMBER = B.PROPOSAL_NUMBER AND P.TRANSACTION_ID = B.TRANSACTION_ID WHERE P.TRANSACTION_ID = @TRANSACTION_ID;";

        // Get Refund Cases using View for Initiating Refunds
        // 30
        public static string GET_REFUND_CASES_VIEW => DataLoader.DBQueriesKeyValueStore["GET_REFUND_CASES_VIEW"]?.ToString() ?? "SELECT * FROM " + VIEW_VW_DPS_REFUND_CASES;

        // Fetch BreakIn PI Sublocation Details
        // 31
        public static string FETCH_NYSA_BREAKIN_PI_SUBLOCATION => DataLoader.DBQueriesKeyValueStore["FETCH_NYSA_BREAKIN_PI_SUBLOCATION"]?.ToString() ?? "SELECT SUBLOCATION FROM " + TABLE_TBL_DPS_NYSA_BREAKIN_PI_SUBLOCATION_MST + " WHERE SUBLOCATION ILIKE @SUBLOCATION ORDER BY SUBLOCATION;";

        // Fetch Application Details from Application Master Table
        // 32
        public static string GET_APPLICATION_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_APPLICATION_DETAILS"]?.ToString() ?? "SELECT JUSPAY_MID, REVERSE_SYNC_URL FROM " + TABLE_TBL_DPS_APPLICATION_MST + " WHERE APPLICATION_NAME = @APPLICATION_NAME LIMIT 1;";

        // Fetch BreakIn Details by Proposal Number
        // 33
        public static string GET_BREAKINDETAILS_BY_PROPOSALNO => DataLoader.DBQueriesKeyValueStore["GET_BREAKINDETAILS_BY_PROPOSALNO"]?.ToString() ?? "SELECT BREAKIN_ID, STATUS, REMARK FROM " + TABLE_TBL_DPS_NYSA_BREAKIN_DETAILS + " WHERE PROPOSAL_NUMBER = @PROPOSAL_NUMBER;";

        // Check if Proposal Exists
        // 34
        public static string CHECK_IF_PROPOSAL_EXISTS => DataLoader.DBQueriesKeyValueStore["CHECK_IF_PROPOSAL_EXISTS"]?.ToString() ?? "SELECT * FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " WHERE PROPOSAL_NUMBER = ANY(@PROPOSAL_LIST);";

        // Get Next DPS ORDER from Sequence
        // 35
        public static string GET_DPS_ORDER_SEQ => DataLoader.DBQueriesKeyValueStore["GET_DPS_ORDER_SEQ"]?.ToString() ?? "SELECT NEXTVAL('" + DB_SCHEMA + "DPS_ORDER_SEQ')";

        // Insert Penny Drop Details
        // 36
        public static string INSERT_PENNY_DROP_DETAILS => DataLoader.DBQueriesKeyValueStore["INSERT_PENNY_DROP_DETAILS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_PENNY_DROP_DETAILS + " (TRACE_ID, BANK_ACCOUNT_NUMBER, BANK_ACCOUNT_HOLDER_NAME, BANK_IFSC_CODE) VALUES (@TRACE_ID, @BANK_ACCOUNT_NUMBER, @BANK_ACCOUNT_HOLDER_NAME, @BANK_IFSC_CODE);";

        // Update Penny Drop Details
        // 37
        public static string UPDATE_PENNY_DROP_DETAILS => DataLoader.DBQueriesKeyValueStore["UPDATE_PENNY_DROP_DETAILS"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_PENNY_DROP_DETAILS + " SET IS_PENNY_DROP_SUCCESS = @IS_PENNY_DROP_SUCCESS, IS_ACCOUNT_VERIFIED = @IS_ACCOUNT_VERIFIED, ACCOUNT_HOLDER_NAME_AT_BANK = @ACCOUNT_HOLDER_NAME_AT_BANK, FUZZY_LOGIC_PERCENTAGE_MATCH = @FUZZY_LOGIC_PERCENTAGE_MATCH, MODIFIED_ON = CURRENT_TIMESTAMP WHERE TRACE_ID = @TRACE_ID;";

