        public static string GET_ILEMI_CAPTURE_MANDATE_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_ILEMI_CAPTURE_MANDATE_DETAILS"]?.ToString() ?? "SELECT ORDER_ID, MANDATE_ID, AMOUNT, CUSTOMER_ID, EXECUTION_DATE AS MANDATE_EXECUTION_DATE, APPLICATION_NAME, TRANSACTION_ID, TRACE_ID FROM " + TABLE_TBL_DPS_EMI_RECURRING_DETAILS + " WHERE TRANSACTION_ID = @TRANSACTION_ID ";

        // Latest Emi Installment
        // 135
        public static string GET_LATEST_EMI_INSTALLMENT => DataLoader.DBQueriesKeyValueStore["GET_LATEST_EMI_INSTALLMENT"]?.ToString() ?? "SELECT * FROM " + TABLE_TBL_DPS_EMI_RECURRING_DETAILS + " WHERE proposal_number = @PROPOSAL_NUMBER ORDER BY INSTALLMENT_NUMBER::int DESC LIMIT 1;";

        // Upsert Emi Installment
        // 136
        public static string UPSERT_EMI_INSTALLMENT_DETAILS => DataLoader.DBQueriesKeyValueStore["UPSERT_EMI_INSTALLMENT_DETAILS"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_EMI_RECURRING_DETAILS + " (recurring_id, transaction_id, trace_id, proposal_number, amount, installment_number, status, payment_id, policy_number, mandate_id, dps_order_id, order_id, payment_mode, due_date, execution_date, grace_end_date, remarks, no_of_attempt, customer_id, application_name) VALUES (@RECURRING_ID, @TRANSACTION_ID, @TRACE_ID, @PROPOSAL_NUMBER, @AMOUNT,@INSTALLMENT_NUMBER, @STATUS, @PAYMENT_ID, @POLICY_NUMBER, @MANDATE_ID, @DPS_ORDER_ID, @ORDER_ID, @PAYMENT_MODE, @DUE_DATE, @EXECUTION_DATE, @GRACE_END_DATE, @REMARKS, @NO_OF_ATTEMPT, @CUSTOMER_ID, @APPLICATION_NAME) ON CONFLICT (proposal_number, installment_number) DO UPDATE SET amount = EXCLUDED.amount, status = EXCLUDED.status, payment_id = EXCLUDED.payment_id, policy_number = EXCLUDED.policy_number, payment_mode = EXCLUDED.payment_mode, execution_date = EXCLUDED.execution_date, remarks = EXCLUDED.remarks, order_id = EXCLUDED.order_id WHERE TBL_DPS_EMI_RECURRING_DETAILS.status <> 'FAILED' RETURNING *;";

        // Get Mandate ID Sequence
        // 137
        public static string GET_RECURRING_ID_SEQ => DataLoader.DBQueriesKeyValueStore["GET_RECURRING_ID_SEQ"]?.ToString() ?? "SELECT NEXTVAL('" + DB_SCHEMA + "RECURRING_ID_SEQ')";

        // Get Gateway Customer ID By MobileNumber
        // 138
        public static string GET_GATEWAY_CUSTOMER_ID_BY_MOBILE_NUMBER => DataLoader.DBQueriesKeyValueStore["GET_GATEWAY_CUSTOMER_ID_BY_MOBILE_NUMBER"]?.ToString() ?? "SELECT GATEWAY_CUSTOMER_ID FROM " + TABLE_TBL_DPS_GATEWAY_CUSTOMER_DETAILS + " WHERE MOBILE_NUMBER = @MOBILE_NUMBER;";

        // Insert Gateway Customer ID
        // 139
        public static string INSERT_GATEWAY_CUSTOMER_ID => DataLoader.DBQueriesKeyValueStore["INSERT_GATEWAY_CUSTOMER_ID"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_GATEWAY_CUSTOMER_DETAILS + " (MOBILE_NUMBER, GATEWAY_CUSTOMER_ID) VALUES (@MOBILE_NUMBER, @GATEWAY_CUSTOMER_ID);";

        // Recurring Installmnent Details
        // 140
        public static string GET_RECURRING_INSTALLMENT_DETAILS => DataLoader.DBQueriesKeyValueStore["GET_RECURRING_INSTALLMENT_DETAILS"]?.ToString() ?? "SELECT * FROM " + TABLE_TBL_DPS_EMI_RECURRING_DETAILS + " WHERE RECURRING_ID = @RECURRING_ID;";

        // Increment No of Attempt for Recurring ID
        // 141
        public static string INCREMENT_NO_OF_RECURRING_ATTEMPT => DataLoader.DBQueriesKeyValueStore["INCREMENT_NO_OF_RECURRING_ATTEMPT"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_EMI_RECURRING_DETAILS + " SET NO_OF_ATTEMPT = NO_OF_ATTEMPT + 1 WHERE RECURRING_ID = @RECURRING_ID;";

        // Fetch DPS Order Status From Order Details Table by Transaction ID
        // 142
        public static string UPDATE_ORDER_STATUS_FOR_ORDER_ID => DataLoader.DBQueriesKeyValueStore["UPDATE_ORDER_STATUS_FOR_ORDER_ID"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_PAYMENT_DETAILS + " SET ORDER_STATUS = @ORDER_STATUS WHERE TRANSACTION_ID = @TRANSACTION_ID AND DPS_ORDER_ID = @DPS_ORDER_ID;";

        // Update Advance Transaction Details v2 for Transaction ID in Transaction Table
        // 143
        public static string UPDATE_ADVANCE_TRANSACTION_DETAILS_V3 => DataLoader.DBQueriesKeyValueStore["UPDATE_ADVANCE_TRANSACTION_DETAILS_V3"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T SET PROPOSAL_NUMBER = @PROPOSAL_NUMBER, PROPOSAL_ID = @PROPOSAL_ID, PROPOSAL_STATUS = @PROPOSAL_STATUS, IS_NSTP_FLOW = @IS_NSTP_FLOW, PROPOSAL_START_DATE = @PROPOSAL_START_DATE, NAME = @NAME, EMAIL = @EMAIL, MOBILE_NUMBER = @MOBILE_NUMBER, PROPOSAL_END_DATE = @PROPOSAL_END_DATE, PROPOSAL_TENURE = @PROPOSAL_TENURE, BASIC_PREMIUM = @BASIC_PREMIUM, GST = @GST, VRN = @VRN, ADDRESS = @ADDRESS, STATE = @STATE, CITY = @CITY, PINCODE = @PINCODE WHERE T.CTID = (SELECT CTID FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " WHERE TRANSACTION_ID = @TRANSACTION_ID AND PROPOSAL_NUMBER IS NULL AND PROPOSAL_TYPE = @PROPOSAL_TYPE AND CORE = @CORE AND PROPOSAL_AMOUNT = @PROPOSAL_AMOUNT LIMIT 1);";

        // Update Advance Payment Details for Transaction ID in Payment Table
        // 144
        public static string UPDATE_ADVANCE_PAYMENT_DETAILS_V3 => DataLoader.DBQueriesKeyValueStore["UPDATE_ADVANCE_PAYMENT_DETAILS_V3"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_PAYMENT_DETAILS + " P SET PROPOSAL_NUMBER = @PROPOSAL_NUMBER WHERE P.CTID = (SELECT CTID FROM " + TABLE_TBL_DPS_PAYMENT_DETAILS + " WHERE TRANSACTION_ID = @TRANSACTION_ID AND PROPOSAL_NUMBER IS NULL LIMIT 1);";

        // Fetch application name for transaction id + trace id
        //145
        public static string GET_TXN_AUTH_DETAILS =>  DataLoader.DBQueriesKeyValueStore["GET_TXN_AUTH_DETAILS"]?.ToString() ?? "SELECT T.APPLICATION_NAME AS USERNAME, A.APPLICATION_ID AS PASSWORD, T.CREATED_ON AS TXN_CREATED_ON, P.CREATED_ON AS PAYMENT_DONE_AT FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T INNER JOIN " +TABLE_TBL_DPS_APPLICATION_MST+ " A ON A.APPLICATION_NAME = T.APPLICATION_NAME LEFT JOIN " + TABLE_TBL_DPS_PAYMENT_DETAILS+ " P ON P.TRANSACTION_ID = T.TRANSACTION_ID WHERE T.TRANSACTION_ID = @TRANSACTION_ID AND T.TRACE_ID = @TRACE_ID LIMIT 1;";

        // Insert Transaction Details received from Channel Application in Transaction Table
        // 146
        public static string INSERT_ADVANCE_TRANSACTION_DETAILS_V3 => DataLoader.DBQueriesKeyValueStore["INSERT_ADVANCE_TRANSACTION_DETAILS_V3"]?.ToString() ?? "INSERT INTO " + TABLE_TBL_DPS_TRANSACTION_DETAILS + "(TRANSACTION_ID, APPLICATION_NAME, TRACE_ID, TOTAL_AMOUNT, PRODUCT, JOURNEY_TYPE, PAYER_TYPE, IS_MOBILE_USER, CHANNEL_APPLICATION_DETAILS, PG_NAME, PAYMENT_FILTERS, JUSPAY_UDF1, JUSPAY_UDF2, JUSPAY_UDF3, JUSPAY_UDF4, JUSPAY_UDF5, JUSPAY_UDF6, JUSPAY_UDF7, JUSPAY_UDF8, JUSPAY_UDF9, JUSPAY_UDF10, PLATFORM, IS_HEADER_REQ, IS_FOOTER_REQ, PRE_PAYMENT_RETURN_URL, DEAL_ID, CUSTOMER_ID, INTERMEDIARY_CODE, PROPOSAL_AMOUNT, PROPOSAL_TYPE, CORE) VALUES(@TRANSACTION_ID, @APPLICATION_NAME, @TRACE_ID, @TOTAL_AMOUNT, @PRODUCT, @JOURNEY_TYPE, @PAYER_TYPE, @IS_MOBILE_USER, @CHANNEL_APPLICATION_DETAILS, @PG_NAME, @PAYMENT_FILTERS, @JUSPAY_UDF1, @JUSPAY_UDF2, @JUSPAY_UDF3, @JUSPAY_UDF4, @JUSPAY_UDF5, @JUSPAY_UDF6, @JUSPAY_UDF7, @JUSPAY_UDF8, @JUSPAY_UDF9, @JUSPAY_UDF10, @PLATFORM, @IS_HEADER_REQ, @IS_FOOTER_REQ, @PRE_PAYMENT_RETURN_URL, @DEAL_ID, @CUSTOMER_ID, @INTERMEDIARY_CODE, @PROPOSAL_AMOUNT, @PROPOSAL_TYPE, @CORE);";

        // Get Advance Payment Details from transaction table for making request body for Payment Entry and Tagging
        // 147
        public static string FETCH_ADVANCE_TXN_DETAILS_V3 => DataLoader.DBQueriesKeyValueStore["FETCH_ADVANCE_TXN_DETAILS_V3"]?.ToString() ?? "WITH TXN AS (SELECT T.TRANSACTION_ID, T.TRACE_ID, T.CREATED_ON, T.CORE, T.TOTAL_AMOUNT, T.PAYER_TYPE, A.PF_MID, A.ARTEMIS_MID, A.REVERSE_SYNC_URL, T.PRODUCT, T.JOURNEY_TYPE, T.APPLICATION_NAME, T.CHANNEL_APPLICATION_DETAILS, T.PROPOSAL_NUMBER, T.PROPOSAL_AMOUNT, T.PROPOSAL_STATUS, T.PROPOSAL_TYPE, T.DEAL_ID, T.CUSTOMER_ID, T.INTERMEDIARY_CODE, T.IS_NSTP_FLOW, T.BUSINESS_VERTICAL, T.SUB_VERTICAL, T.MARKETING_OFFICER, T.PROPOSER_CODE, ROW_NUMBER() OVER (PARTITION BY T.TRANSACTION_ID, T.PROPOSAL_AMOUNT, T.PROPOSAL_TYPE, T.CORE ORDER BY T.CREATED_ON, T.CTID) AS RN FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " T INNER JOIN " + TABLE_TBL_DPS_APPLICATION_MST + " A ON A.APPLICATION_NAME = T.APPLICATION_NAME WHERE T.TRANSACTION_ID = @TRANSACTION_ID), PAY AS (SELECT P.TRANSACTION_ID, P.PROPOSAL_NUMBER, P.PROPOSAL_AMOUNT, P.PROPOSAL_TYPE, P.CORE, P.DPS_ORDER_ID, P.PAYMENT_MODE, P.AUTH_CODE, P.PAYMENT_ID, P.POLICY_NUMBER, ROW_NUMBER() OVER (PARTITION BY P.TRANSACTION_ID, P.PROPOSAL_AMOUNT, P.PROPOSAL_TYPE, P.CORE ORDER BY P.CREATED_ON, P.CTID) AS RN FROM " + TABLE_TBL_DPS_PAYMENT_DETAILS + " P WHERE P.TRANSACTION_ID = @TRANSACTION_ID) SELECT TXN.TRANSACTION_ID, TXN.TRACE_ID, TXN.CREATED_ON, TXN.CORE, TXN.TOTAL_AMOUNT, TXN.PAYER_TYPE, TXN.PF_MID, TXN.ARTEMIS_MID, TXN.REVERSE_SYNC_URL, TXN.PRODUCT, TXN.JOURNEY_TYPE, TXN.APPLICATION_NAME, TXN.CHANNEL_APPLICATION_DETAILS, TXN.PROPOSAL_NUMBER, TXN.PROPOSAL_AMOUNT, TXN.PROPOSAL_STATUS, TXN.PROPOSAL_TYPE, TXN.DEAL_ID, TXN.CUSTOMER_ID, TXN.INTERMEDIARY_CODE, TXN.IS_NSTP_FLOW, TXN.BUSINESS_VERTICAL, TXN.SUB_VERTICAL, TXN.MARKETING_OFFICER, TXN.PROPOSER_CODE, PAY.DPS_ORDER_ID, PAY.PAYMENT_MODE, PAY.AUTH_CODE, PAY.PAYMENT_ID, PAY.POLICY_NUMBER FROM TXN LEFT JOIN PAY ON TXN.TRANSACTION_ID = PAY.TRANSACTION_ID AND TXN.PROPOSAL_AMOUNT IS NOT DISTINCT FROM PAY.PROPOSAL_AMOUNT AND TXN.PROPOSAL_TYPE IS NOT DISTINCT FROM PAY.PROPOSAL_TYPE AND TXN.CORE IS NOT DISTINCT FROM PAY.CORE AND TXN.RN = PAY.RN ORDER BY TXN.CREATED_ON;";
        
        // Get Advance Payment Details from payment table for making request body for Payment Entry and Tagging
