        public static string FETCH_ADVANCE_TXN_ORDER_DETAILS_V3 => DataLoader.DBQueriesKeyValueStore["FETCH_ADVANCE_TXN_ORDER_DETAILS_V3"]?.ToString() ?? "SELECT DPS_ORDER_ID, PAYMENT_MODE, AUTH_CODE FROM " + TABLE_TBL_DPS_PAYMENT_DETAILS + " WHERE TRANSACTION_ID = @TRANSACTION_ID;";

