        public static string FETCH_ADVANCE_PAYMENT_DETAILS_V3 => DataLoader.DBQueriesKeyValueStore["FETCH_ADVANCE_PAYMENT_DETAILS_V3"]?.ToString() ?? "SELECT DEAL_ID, CUSTOMER_ID, INTERMEDIARY_CODE, BUSINESS_VERTICAL, SUB_VERTICAL, MARKETING_OFFICER, PROPOSER_CODE FROM " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " WHERE TRANSACTION_ID = @TRANSACTION_ID AND PROPOSAL_AMOUNT = @PROPOSAL_AMOUNT AND PROPOSAL_TYPE = @PROPOSAL_TYPE AND CORE = @CORE;";
        
