        public static string UPDATE_ILEMI_PROPOSAL_MODIFIED_STATUS => DataLoader.DBQueriesKeyValueStore["UPDATE_ILEMI_PROPOSAL_MODIFIED_STATUS"]?.ToString() ?? "UPDATE " + TABLE_TBL_DPS_TRANSACTION_DETAILS + " SET IS_ILEMI_PROPOSAL_MODIFIED = @IS_ILEMI_PROPOSAL_MODIFIED WHERE TRANSACTION_ID = @TRANSACTION_ID AND PROPOSAL_ID = @PROPOSAL_ID;";

